<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Factories\HasFactory;
class Item extends Model { use HasFactory; protected $table='items'; protected $guarded=[]; protected $casts=['is_active'=>'boolean','is_discontinued'=>'boolean','price_hold'=>'boolean','can_be_sold'=>'boolean','can_be_purchased'=>'boolean','track_serial'=>'boolean','track_batch'=>'boolean']; public function baseUom(){return $this->belongsTo(Uom::class,'base_uom_id');} public function inventoryPostingGroup(){return $this->belongsTo(InventoryPostingGroup::class);} public function generalProductPostingGroup(){return $this->belongsTo(GeneralProductPostingGroup::class);} public function taxPostingGroup(){return $this->belongsTo(TaxPostingGroup::class);} public function category(){return $this->belongsTo(ItemCategory::class);} public function brand(){return $this->belongsTo(Brand::class);} public function uoms(){return $this->hasMany(ItemUom::class);} public function prices(){return $this->hasMany(\App\Models\Pricing\ItemPrice::class);} public function defaultVendor(){return $this->belongsTo(Vendor::class,'default_vendor_id');} public function isTransactionEligible(): bool{return $this->is_active && !$this->is_discontinued && !$this->price_hold;} }
